    inFlight: async () => sys.inFlight(),
    deliver: async (id) => sys.deliver(id),
    deliverAll: async () => sys.deliverAll(),
  };
}

const createHost: CreateHost = async () => hostOf(new LeaseSystem());

export default createHost;

