// Capture NDJSON traces from the real implementation (src/lease.ts) through its onStep seam.
// Run: node spec/capture.ts   → spec/traces/*.ndjson

import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { LeaseSystem } from '../src/lease.ts';
import type { Message } from '../src/types.ts';

const enc = (m: Message) =>
  `${m.action}|${m.from}|${m.to}|${m.data.token === undefined ? '' : m.data.token}`;

function project(sys: LeaseSystem) {
  const out: Record<string, unknown> = {
    holder: sys.service.holder,
    token: sys.service.token,
    writes: sys.service.writes,
  };
  for (const c of ['c0', 'c1'] as const) {
    const s = sys.clients[c];
    out[c + 'Status'] = s.status;
    out[c + 'Token'] = s.token;
    out[c + 'Writing'] = s.writing;
    out[c + 'Revoked'] = s.revoked;
  }
  out.net = [...sys.network.values()].map(enc).sort();
  return out;
}

function traced(): { sys: LeaseSystem; lines: string[] } {
  const sys = new LeaseSystem();
  const lines: string[] = [];
  let pre: Record<string, unknown> | null = null;
  let action = '';
  let data: Record<string, unknown> = {};
  sys.onStep((phase, ev) => {
    if (phase === 'pre') {
      pre = project(sys);
      if (ev.kind === 'deliver') {
        action = 'DELIVER';
        data = { i: (pre.net as string[]).indexOf(enc(ev.args.message as Message)) };
      } else {
        action = ev.name.toUpperCase();
        data = ev.name === 'expire' ? {} : { client: ev.args.client };
      }
    } else {
      lines.push(JSON.stringify({ pre, action, data, post: project(sys) }));
    }
  });
  return { sys, lines };
}

const deliverWhere = (sys: LeaseSystem, action: string) => {
  const m = sys.inFlight().find((x) => x.action === action);
  if (!m) throw new Error(`no ${action} in flight`);
  sys.deliver(m.id);
};

const scenarios: Record<string, (sys: LeaseSystem) => void> = {
  normal(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.write('c0'); sys.write('c0'); sys.deliverAll();
    sys.release('c0'); sys.release('c0'); sys.deliverAll();
  },
  refusals(sys) {
    sys.acquire('c2'); sys.release('c2'); sys.write('c2'); sys.expire();
    sys.release('c0'); sys.write('c1');
    sys.acquire('c1'); sys.acquire('c1'); sys.deliverAll();
  },
  denied_while_held(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.acquire('c1'); sys.deliverAll();
    sys.expire(); sys.deliverAll();
    sys.acquire('c1'); sys.deliverAll();
    sys.release('c1'); sys.deliverAll();
    sys.acquire('c0'); sys.deliverAll(); // grant cap
  },
  stale_write(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.write('c0'); sys.expire();
    deliverWhere(sys, 'Write'); deliverWhere(sys, 'WriteRefused');
    sys.acquire('c1'); sys.deliverAll();
  },
  revoked_before_granted(sys) {
    sys.acquire('c0'); deliverWhere(sys, 'Acquire');
    sys.expire(); deliverWhere(sys, 'Revoked'); deliverWhere(sys, 'Granted');
    sys.acquire('c0'); sys.deliverAll();
    sys.expire(); sys.deliverAll();
  },
  write_cap(sys) {
    sys.acquire('c1'); sys.deliverAll();
    for (let i = 0; i < 3; i++) { sys.write('c1'); sys.deliverAll(); }
  },
  release_after_expire(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.release('c0'); sys.expire();
    deliverWhere(sys, 'Revoked'); deliverWhere(sys, 'Release');
    sys.acquire('c0'); sys.deliverAll();
  },
};

// random schedules for breadth
for (let r = 0; r < 20; r++) {
  scenarios[`random_${r}`] = (sys) => {
    let seed = 1000 + r;
    const rnd = (n: number) => ((seed = (seed * 1103515245 + 12345) % 2147483648), seed % n);
    for (let i = 0; i < 40; i++) {
      const c = ['c0', 'c1', 'c2'][rnd(3)];
      const k = rnd(6);
      if (k === 0) sys.acquire(c);
      else if (k === 1) sys.release(c);
      else if (k === 2) sys.write(c);
      else if (k === 3) sys.expire();
      else {
        const fl = sys.inFlight();
        if (fl.length) sys.deliver(fl[rnd(fl.length)].id);
      }
    }
    sys.deliverAll();
  };
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, run] of Object.entries(scenarios)) {
  const { sys, lines } = traced();
  run(sys);
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log(`wrote ${Object.keys(scenarios).length} traces`);

