// Negative control (mutate.mjs needs polynv/, absent here): apply targeted mutations to
// lease.spec.cjs, write each to spec/mutants/, and replay + model-check them with verify.mjs.
// Run: node spec/mutants.mjs
import { readFileSync, writeFileSync, mkdirSync, rmSync } from 'node:fs';
import { execFileSync } from 'node:child_process';

const src = readFileSync(new URL('./lease.spec.cjs', import.meta.url), 'utf-8');
const MUTANTS = {
  'write-no-fencing': ["model.holder === from && m.token === model.token && model.writes < MAX_WRITES", 'model.writes < MAX_WRITES'],
  'write-no-cap': ["m.token === model.token && model.writes < MAX_WRITES", 'm.token === model.token'],
  'grant-no-cap': ['model.holder === null && model.token < MAX_GRANTS', 'model.holder === null'],
  'grant-while-held': ['model.holder === null && model.token < MAX_GRANTS', 'model.token < MAX_GRANTS'],
  'release-no-token-check': ['model.holder === from && m.token === model.token) writes.holder = null', 'model.holder === from) writes.holder = null'],
  'no-revoked-memory': ["m.token <= model[c + 'Revoked'] ? 'idle' : 'holding'", "'holding'"],
  'revoked-any-token': ["if (m.token === model[c + 'Token']) writes[c + 'Status'] = 'idle';", "writes[c + 'Status'] = 'idle';"],
  'write-pending-ignored': ["if (model[c + 'Writing']) return reject('write-pending');", ''],
};

const dir = new URL('./mutants/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, [from, to]] of Object.entries(MUTANTS)) {
  if (!src.includes(from)) throw new Error(`mutant ${name}: pattern not found`);
  writeFileSync(new URL(`${name}.cjs`, dir), src.replace(from, to));
}
const out = execFileSync(process.execPath, [
  'tools/polygraph/scripts/verify.mjs', '--contract', 'spec/contract.json', '--traces', 'spec/traces/',
  '--specs', 'spec/mutants', '--out', 'spec/out-mutants', '--invariants', 'spec/invariants.mjs',
], { encoding: 'utf-8', stdio: ['ignore', 'pipe', 'ignore'] });
console.log(out);

