import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

async function deliverWhere(h: Host, pred: (m: { action: string; to: string }) => boolean) {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
}

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c2'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.client('c0'))!.status, 'requesting');
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual(
    { from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } },
  );
  assert.equal((await h.acquire('c0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.client('c0'))!.writing, true);
  await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  assert.equal((await h.client('c0'))!.writing, false);
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.equal((await h.release('c0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
});

test('unknown clients and expire refused', async () => {
  const h = await createHost();
  for (const c of ['c2', '', 'lease']) {
    assert.equal((await h.acquire(c)).ok, false);
    assert.equal((await h.release(c)).ok, false);
    assert.equal((await h.write(c)).ok, false);
  }
  assert.equal((await h.expire()).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
});

test('denied while held, and at most 2 grants', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.acquire('c1');
  await h.deliverAll();
  assert.equal((await h.client('c1'))!.status, 'idle');
  await h.expire();
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  await h.acquire('c1');
  await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1');
  await h.deliverAll();
  await h.acquire('c0');
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('stale write is refused (fencing)', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.write('c0');
  await h.expire();
  await deliverWhere(h, (m) => m.action === 'Write');
  await deliverWhere(h, (m) => m.action === 'WriteRefused');
  assert.equal((await h.lease()).writes, 0);
  assert.equal((await h.client('c0'))!.writing, false);
});

test('revoked before granted', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await deliverWhere(h, (m) => m.action === 'Acquire');
  await h.expire();
  await deliverWhere(h, (m) => m.action === 'Revoked');
  assert.equal((await h.client('c0'))!.status, 'requesting');
  await deliverWhere(h, (m) => m.action === 'Granted');
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.equal((await h.lease()).holder, null);
});

test('at most 2 writes', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  for (let i = 0; i < 3; i++) {
    await h.write('c0');
    await h.deliverAll();
  }
  assert.equal((await h.lease()).writes, 2);
});

test('random schedules keep the conclusion', async () => {
  let seed = 7;
  const rnd = (n: number) => ((seed = (seed * 1103515245 + 12345) % 2147483648), seed % n);
  for (let run = 0; run < 300; run++) {
    const h = await createHost();
    for (let i = 0; i < 40; i++) {
      const c = ['c0', 'c1'][rnd(2)];
      const k = rnd(6);
      if (k === 0) await h.acquire(c);
      else if (k === 1) await h.release(c);
      else if (k === 2) await h.write(c);
      else if (k === 3) await h.expire();
      else {
        const fl = await h.inFlight();
        if (fl.length) await h.deliver(fl[rnd(fl.length)].id);
      }
      const l = await h.lease();
      const holders = [];
      for (const id of ['c0', 'c1']) {
        const v = (await h.client(id))!;
        if (v.status === 'holding' && v.token === l.token) holders.push(id);
      }
      assert.ok(holders.length <= 1);
    }
    await h.deliverAll();
    const l = await h.lease();
    for (const id of ['c0', 'c1']) {
      const v = (await h.client(id))!;
      assert.equal(v.status === 'holding', l.holder === id, `run ${run}`);
    }
  }
});

