      if (!isClient(client)) return refuse('unknown client');
      const c = this.clients[client];
      if (c.status !== 'holding') return refuse('client does not hold the lease');
      c.status = 'idle';
      this.send(client, SERVICE, 'Release', { from: client, token: c.token });
      return ok;
    });
