import { test } from 'node:test';
import assert from 'node:assert/strict';
import createHost from '../src/host.impl.ts';
import type { Host } from '../src/types.ts';

async function deliverWhere(h: Host, pred: (m: { action: string; to: string }) => boolean) {
  const m = (await h.inFlight()).find(pred);
  assert.ok(m, 'expected message in flight');
  await h.deliver(m.id);
}

test('fresh system', async () => {
  const h = await createHost();
  assert.deepEqual(await h.lease(), { holder: null, token: 0, writes: 0 });
  assert.deepEqual(await h.client('c0'), { status: 'idle', token: 0, writing: false });
  assert.equal(await h.client('c2'), null);
  assert.deepEqual(await h.inFlight(), []);
});

test('acquire, write, release', async () => {
  const h = await createHost();
  assert.deepEqual(await h.acquire('c0'), { ok: true });
  assert.equal((await h.client('c0'))!.status, 'requesting');
  const msgs = await h.inFlight();
  assert.equal(msgs.length, 1);
  assert.deepEqual(
    { from: msgs[0].from, to: msgs[0].to, action: msgs[0].action, data: msgs[0].data },
    { from: 'c0', to: 'lease', action: 'Acquire', data: { from: 'c0' } },
  );
  assert.equal((await h.acquire('c0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.client('c0'), { status: 'holding', token: 1, writing: false });
  assert.deepEqual(await h.lease(), { holder: 'c0', token: 1, writes: 0 });
  assert.deepEqual(await h.write('c0'), { ok: true });
  assert.equal((await h.write('c0')).ok, false);
  assert.equal((await h.client('c0'))!.writing, true);
  await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
  assert.equal((await h.client('c0'))!.writing, false);
  assert.deepEqual(await h.release('c0'), { ok: true });
  assert.equal((await h.release('c0')).ok, false);
  await h.deliverAll();
  assert.deepEqual(await h.lease(), { holder: null, token: 1, writes: 1 });
});

test('unknown clients and expire refused', async () => {
  const h = await createHost();
  for (const c of ['c2', '', 'lease']) {
    assert.equal((await h.acquire(c)).ok, false);
    assert.equal((await h.release(c)).ok, false);
    assert.equal((await h.write(c)).ok, false);
  }
  assert.equal((await h.expire()).ok, false);
  assert.equal((await h.write('c0')).ok, false);
  assert.deepEqual(await h.inFlight(), []);
});

test('denied while held, and at most 2 grants', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.acquire('c1');
  await h.deliverAll();
  assert.equal((await h.client('c1'))!.status, 'idle');
  await h.expire();
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  await h.acquire('c1');
  await h.deliverAll();
  assert.deepEqual(await h.client('c1'), { status: 'holding', token: 2, writing: false });
  await h.release('c1');
  await h.deliverAll();
  await h.acquire('c0');
  await h.deliverAll();
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.deepEqual(await h.lease(), { holder: null, token: 2, writes: 0 });
});

test('stale write is refused (fencing)', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.write('c0');
  await h.expire();
  await deliverWhere(h, (m) => m.action === 'Write');
  await deliverWhere(h, (m) => m.action === 'WriteRefused');
  assert.equal((await h.lease()).writes, 0);
  assert.equal((await h.client('c0'))!.writing, false);
});

test('revoked before granted', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await deliverWhere(h, (m) => m.action === 'Acquire');
  await h.expire();
  await deliverWhere(h, (m) => m.action === 'Revoked');
  assert.equal((await h.client('c0'))!.status, 'requesting');
  await deliverWhere(h, (m) => m.action === 'Granted');
  assert.equal((await h.client('c0'))!.status, 'idle');
  assert.equal((await h.lease()).holder, null);
});

test('one write per grant, at most 2 writes', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  for (let i = 0; i < 3; i++) {
    assert.deepEqual(await h.write('c0'), { ok: true });
    await h.deliverAll();
  }
  assert.equal((await h.lease()).writes, 1);
  await h.release('c0');
  await h.deliverAll();
  await h.acquire('c1');
  await h.deliverAll();
  for (let i = 0; i < 2; i++) {
    await h.write('c1');
    await h.deliverAll();
  }
  assert.deepEqual(await h.lease(), { holder: 'c1', token: 2, writes: 2 });
});

test('second write in flight under same grant is refused', async () => {
  const h = await createHost();
  await h.acquire('c0');
  await h.deliverAll();
  await h.write('c0');
  await deliverWhere(h, (m) => m.action === 'Write');
  await deliverWhere(h, (m) => m.action === 'WriteDone');
  await h.write('c0');
  await deliverWhere(h, (m) => m.action === 'Write');
  const fl = await h.inFlight();
  assert.deepEqual(fl.map((m) => m.action), ['WriteRefused']);
  await h.deliverAll();
  assert.equal((await h.lease()).writes, 1);
});

test('random schedules keep the conclusion', async () => {
  let seed = 7;
  const rnd = (n: number) => ((seed = (seed * 1103515245 + 12345) % 2147483648), seed % n);
  for (let run = 0; run < 300; run++) {
    const h = await createHost();
    for (let i = 0; i < 40; i++) {
      const c = ['c0', 'c1'][rnd(2)];
      const k = rnd(6);
      if (k === 0) await h.acquire(c);
      else if (k === 1) await h.release(c);
      else if (k === 2) await h.write(c);
      else if (k === 3) await h.expire();
      else {
        const fl = await h.inFlight();
        if (fl.length) await h.deliver(fl[rnd(fl.length)].id);
      }
      const l = await h.lease();
      const holders = [];
      for (const id of ['c0', 'c1']) {
        const v = (await h.client(id))!;
        if (v.status === 'holding' && v.token === l.token) holders.push(id);
      }
      assert.ok(holders.length <= 1);
    }
    await h.deliverAll();
    const l = await h.lease();
    for (const id of ['c0', 'c1']) {
      const v = (await h.client(id))!;
      assert.equal(v.status === 'holding', l.holder === id, `run ${run}`);
    }
  }
});

'use strict';

// SAM v2 strict-profile specification of src/lease.ts: the lease service, the
// clients c0 and c1, and the network. The network is a sorted array of encoded
// messages "Action|from|to|token" (token empty when the message carries none);
// DELIVER { i } delivers the i-th message of that sorted array.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_GRANTS = 2;
const MAX_WRITES = 2;
const CLIENTS = ['c0', 'c1'];

const INITIAL_STATE = {
  holder: null,
  token: 0,
  writes: 0,
  grantWritten: false,
  c0Status: 'idle', c0Token: 0, c0Writing: false, c0Revoked: 0,
  c1Status: 'idle', c1Token: 0, c1Writing: false, c1Revoked: 0,
  net: [],
};

const enc = (action, from, to, token) => `${action}|${from}|${to}|${token === undefined ? '' : token}`;
const dec = (s) => {
  const [action, from, to, token] = s.split('|');
  return { action, from, to, token: token === '' ? undefined : Number(token) };
};
const withMsgs = (net, add) => [...net, ...add].sort();
const without = (net, i) => net.filter((_, j) => j !== i);
const isClient = (c) => CLIENTS.includes(c);

const clientIntent = () => ({ action: (data = {}) => ({ ...data }), schema: { client: 'string' }, domain: [{ client: 'c0' }, { client: 'c1' }, { client: 'c2' }] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      holder: { type: 'string', nullable: true },
      token: { type: 'number' },
      writes: { type: 'number' },
      grantWritten: { type: 'boolean' },
      c0Status: { type: 'string' }, c0Token: { type: 'number' }, c0Writing: { type: 'boolean' }, c0Revoked: { type: 'number' },
      c1Status: { type: 'string' }, c1Token: { type: 'number' }, c1Writing: { type: 'boolean' }, c1Revoked: { type: 'number' },
      net: { type: 'array' },
    },
    actions: {
      ACQUIRE: clientIntent(),
      RELEASE: clientIntent(),
      WRITE: clientIntent(),
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { i: 'number' },
        domain: [0, 1, 2, 3, 4, 5, 6, 7].map((i) => ({ i })),
      },
    },
    acceptors: {
      ACQUIRE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'idle') return reject('client-not-idle');
        next[c + 'Status'] = 'requesting';
        next.net = withMsgs(model.net, [enc('Acquire', c, 'lease')]);
        unchanged(...otherKeys([c + 'Status', 'net']));
      },
      RELEASE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'holding') return reject('client-not-holding');
        next[c + 'Status'] = 'idle';
        next.net = withMsgs(model.net, [enc('Release', c, 'lease', model[c + 'Token'])]);
        unchanged(...otherKeys([c + 'Status', 'net']));
      },
      WRITE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'holding') return reject('client-not-holding');
        if (model[c + 'Writing']) return reject('write-pending');
        next[c + 'Writing'] = true;
        next.net = withMsgs(model.net, [enc('Write', c, 'lease', model[c + 'Token'])]);
        unchanged(...otherKeys([c + 'Writing', 'net']));
      },
      EXPIRE: (model) => (p, { reject, next, unchanged }) => {
        if (model.holder === null) return reject('no-holder');
        next.holder = null;
        next.net = withMsgs(model.net, [enc('Revoked', 'lease', model.holder, model.token)]);
        unchanged(...otherKeys(['holder', 'net']));
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        const i = p.i;
        if (!Number.isInteger(i) || i < 0 || i >= model.net.length) return reject('no-such-message');
        const m = dec(model.net[i]);
        const rest = without(model.net, i);
        const writes = {};
        if (m.to === 'lease') {
          const from = m.from;
          if (m.action === 'Acquire') {
            if (model.holder === null && model.token < MAX_GRANTS) {
              const t = model.token + 1;
              writes.token = t;
              writes.holder = from;
              writes.grantWritten = false;
              writes.net = withMsgs(rest, [enc('Granted', 'lease', from, t)]);
            } else {
              writes.net = withMsgs(rest, [enc('Denied', 'lease', from)]);
            }
          } else if (m.action === 'Release') {
            if (model.holder === from && m.token === model.token) writes.holder = null;
            writes.net = rest;
          } else if (m.action === 'Write') {
            if (model.holder === from && m.token === model.token && !model.grantWritten && model.writes < MAX_WRITES) {
              writes.writes = model.writes + 1;
              writes.grantWritten = true;
              writes.net = withMsgs(rest, [enc('WriteDone', 'lease', from)]);
            } else {
              writes.net = withMsgs(rest, [enc('WriteRefused', 'lease', from)]);
            }
          } else {
            writes.net = rest;
          }
        } else {
          const c = m.to;
          const status = model[c + 'Status'];
          writes.net = rest;
          if (m.action === 'Granted') {
            if (status === 'requesting') {
              writes[c + 'Token'] = m.token;
              writes[c + 'Status'] = m.token <= model[c + 'Revoked'] ? 'idle' : 'holding';
            }
          } else if (m.action === 'Denied') {
            if (status === 'requesting') writes[c + 'Status'] = 'idle';
          } else if (m.action === 'Revoked') {
            if (status === 'holding') {
              if (m.token === model[c + 'Token']) writes[c + 'Status'] = 'idle';
            } else if (m.token > model[c + 'Revoked']) {
              writes[c + 'Revoked'] = m.token;
            }
          } else if (m.action === 'WriteDone' || m.action === 'WriteRefused') {
            writes[c + 'Writing'] = false;
          }
        }
        for (const [k, v] of Object.entries(writes)) next[k] = v;
        unchanged(...otherKeys(Object.keys(writes)));
      },
    },
    reactors: [],
  },
});

function otherKeys(assigned) {
  return Object.keys(INITIAL_STATE).filter((k) => !assigned.includes(k));
}

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
