// Rules the brief requires, over the state of spec/lease.spec.cjs.

const CLIENTS = ['c0', 'c1'];
const dec = (s) => {
  const [action, from, to, token] = s.split('|');
  return { action, from, to, token: token === '' ? undefined : Number(token) };
};

export const stateInvariants = [
  { name: 'at-most-2-grants', pred: (s) => s.token >= 0 && s.token <= 2 },
  { name: 'at-most-2-writes', pred: (s) => s.writes >= 0 && s.writes <= 2 },
  {
    name: 'at-most-one-holder-with-current-token',
    pred: (s) => CLIENTS.filter((c) => s[c + 'Status'] === 'holding' && s[c + 'Token'] === s.token).length <= 1,
  },
  {
    name: 'holding-client-has-a-real-token',
    pred: (s) => CLIENTS.every((c) => s[c + 'Status'] !== 'holding' || (s[c + 'Token'] >= 1 && s[c + 'Token'] <= s.token)),
  },
  {
    name: 'service-holder-has-current-token-grant',
    // the service's holder holds the current token, or its Granted / its Release is still in flight
    pred: (s) =>
      s.holder === null ||
      (s[s.holder + 'Status'] === 'holding' && s[s.holder + 'Token'] === s.token) ||
      s.net.includes(`Granted|lease|${s.holder}|${s.token}`) ||
      s.net.includes(`Release|${s.holder}|lease|${s.token}`),
  },
  {
    name: 'quiescent-agreement',
    // once no message is in transit, a client holds exactly when the service says it does
    pred: (s) => s.net.length > 0 || CLIENTS.every((c) => (s[c + 'Status'] === 'holding') === (s.holder === c)),
  },
  {
    name: 'writing-flag-matches-net',
    // a client is writing exactly when its Write or the answer to it is in transit
    pred: (s) =>
      CLIENTS.every((c) => {
        const n = s.net.filter((m) => {
          const d = dec(m);
          return (d.action === 'Write' && d.from === c) || ((d.action === 'WriteDone' || d.action === 'WriteRefused') && d.to === c);
        }).length;
        return n === (s[c + 'Writing'] ? 1 : 0);
      }),
  },
  {
    name: 'one-write-per-grant',
    // each grant took at most one write; the current one counts only once it took its write
    pred: (s) => s.writes + (s.token > 0 && !s.grantWritten ? 1 : 0) <= s.token,
  },
  { name: 'network-bounded', pred: (s) => s.net.length <= 8 },
];

export const transitionInvariants = [
  {
    name: 'writes-only-from-current-holder',
    pred: (pre, action, data, post) => {
      if (post.writes === pre.writes) return true;
      if (action !== 'DELIVER' || post.writes !== pre.writes + 1) return false;
      const m = dec(pre.net[data.i]);
      return m.action === 'Write' && m.from === pre.holder && m.token === pre.token;
    },
  },
  {
    name: 'no-second-write-under-same-grant',
    pred: (pre, _a, _d, post) => !(post.writes > pre.writes && pre.grantWritten && post.token === pre.token),
  },
  {
    name: 'tokens-and-writes-monotone',
    pred: (pre, _a, _d, post) => post.token >= pre.token && post.writes >= pre.writes,
  },
  {
    name: 'grant-uses-next-token',
    pred: (pre, _a, _d, post) => post.token === pre.token || (post.token === pre.token + 1 && pre.holder === null && post.holder !== null),
  },
];

