'use strict';

// SAM v2 strict-profile specification of src/lease.ts: the lease service, the
// clients c0 and c1, and the network. The network is a sorted array of encoded
// messages "Action|from|to|token" (token empty when the message carries none);
// DELIVER { i } delivers the i-th message of that sorted array.

const { createInstance } = require('@cognitive-fab/sam-pattern');

const instance = createInstance({ strict: true, hasAsyncActions: false });

const MAX_GRANTS = 2;
const MAX_WRITES = 2;
const CLIENTS = ['c0', 'c1'];

const INITIAL_STATE = {
  holder: null,
  token: 0,
  writes: 0,
  grantWritten: false,
  c0Status: 'idle', c0Token: 0, c0Writing: false, c0Revoked: 0,
  c1Status: 'idle', c1Token: 0, c1Writing: false, c1Revoked: 0,
  net: [],
};

const enc = (action, from, to, token) => `${action}|${from}|${to}|${token === undefined ? '' : token}`;
const dec = (s) => {
  const [action, from, to, token] = s.split('|');
  return { action, from, to, token: token === '' ? undefined : Number(token) };
};
const withMsgs = (net, add) => [...net, ...add].sort();
const without = (net, i) => net.filter((_, j) => j !== i);
const isClient = (c) => CLIENTS.includes(c);

const clientIntent = () => ({ action: (data = {}) => ({ ...data }), schema: { client: 'string' }, domain: [{ client: 'c0' }, { client: 'c1' }, { client: 'c2' }] });

const control = instance({
  initialState: { ...INITIAL_STATE },
  component: {
    modelShape: {
      holder: { type: 'string', nullable: true },
      token: { type: 'number' },
      writes: { type: 'number' },
      grantWritten: { type: 'boolean' },
      c0Status: { type: 'string' }, c0Token: { type: 'number' }, c0Writing: { type: 'boolean' }, c0Revoked: { type: 'number' },
      c1Status: { type: 'string' }, c1Token: { type: 'number' }, c1Writing: { type: 'boolean' }, c1Revoked: { type: 'number' },
      net: { type: 'array' },
    },
    actions: {
      ACQUIRE: clientIntent(),
      RELEASE: clientIntent(),
      CANCEL_ACQUIRE: clientIntent(),
      WRITE: clientIntent(),
      EXPIRE: { action: (data = {}) => ({ ...data }), schema: {}, domain: [{}] },
      DELIVER: {
        action: (data = {}) => ({ ...data }),
        schema: { i: 'number' },
        domain: [0, 1, 2, 3, 4, 5, 6, 7].map((i) => ({ i })),
      },
    },
    acceptors: {
      ACQUIRE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'idle') return reject('client-not-idle');
        next[c + 'Status'] = 'requesting';
        next.net = withMsgs(model.net, [enc('Acquire', c, 'lease')]);
        unchanged(...otherKeys([c + 'Status', 'net']));
      },
      RELEASE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'holding') return reject('client-not-holding');
        next[c + 'Status'] = 'releasing';
        next.net = withMsgs(model.net, [enc('Release', c, 'lease', model[c + 'Token'])]);
        unchanged(...otherKeys([c + 'Status', 'net']));
      },
      CANCEL_ACQUIRE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'requesting') return reject('client-not-requesting');
        next[c + 'Status'] = 'abandoning';
        unchanged(...otherKeys([c + 'Status']));
      },
      WRITE: (model) => (p, { reject, next, unchanged }) => {
        const c = p.client;
        if (!isClient(c)) return reject('unknown-client');
        if (model[c + 'Status'] !== 'holding') return reject('client-not-holding');
        if (model[c + 'Writing']) return reject('write-pending');
        next[c + 'Writing'] = true;
        next.net = withMsgs(model.net, [enc('Write', c, 'lease', model[c + 'Token'])]);
        unchanged(...otherKeys([c + 'Writing', 'net']));
      },
      EXPIRE: (model) => (p, { reject, next, unchanged }) => {
        if (model.holder === null) return reject('no-holder');
        next.holder = null;
        next.net = withMsgs(model.net, [enc('Revoked', 'lease', model.holder, model.token)]);
        unchanged(...otherKeys(['holder', 'net']));
      },
      DELIVER: (model) => (p, { reject, next, unchanged }) => {
        const i = p.i;
        if (!Number.isInteger(i) || i < 0 || i >= model.net.length) return reject('no-such-message');
        const m = dec(model.net[i]);
        const rest = without(model.net, i);
        const writes = {};
        if (m.to === 'lease') {
          const from = m.from;
          if (m.action === 'Acquire') {
            if (model.holder === null && model.token < MAX_GRANTS) {
              const t = model.token + 1;
              writes.token = t;
              writes.holder = from;
              writes.grantWritten = false;
              writes.net = withMsgs(rest, [enc('Granted', 'lease', from, t)]);
            } else {
              writes.net = withMsgs(rest, [enc('Denied', 'lease', from)]);
            }
          } else if (m.action === 'Release') {
            if (model.holder === from && m.token === model.token) writes.holder = null;
            writes.net = withMsgs(rest, [enc('Released', 'lease', from)]);
          } else if (m.action === 'Write') {
            if (model.holder === from && m.token === model.token && !model.grantWritten && model.writes < MAX_WRITES) {
              writes.writes = model.writes + 1;
              writes.grantWritten = true;
              writes.net = withMsgs(rest, [enc('WriteDone', 'lease', from)]);
            } else {
              writes.net = withMsgs(rest, [enc('WriteRefused', 'lease', from)]);
            }
          } else {
            writes.net = rest;
          }
        } else {
          const c = m.to;
          const status = model[c + 'Status'];
          writes.net = rest;
          if (m.action === 'Granted') {
            if (status === 'abandoning') {
              writes[c + 'Token'] = m.token;
              writes[c + 'Status'] = 'releasing';
              writes.net = withMsgs(rest, [enc('Release', c, 'lease', m.token)]);
            } else if (status === 'requesting') {
              writes[c + 'Token'] = m.token;
              writes[c + 'Status'] = m.token <= model[c + 'Revoked'] ? 'idle' : 'holding';
            }
          } else if (m.action === 'Denied') {
            if (status === 'requesting' || status === 'abandoning') writes[c + 'Status'] = 'idle';
          } else if (m.action === 'Released') {
            if (status === 'releasing') writes[c + 'Status'] = 'idle';
          } else if (m.action === 'Revoked') {
            if (status === 'releasing') {
              // a releasing client ignores Revoked
            } else if (status === 'holding') {
              if (m.token === model[c + 'Token']) writes[c + 'Status'] = 'idle';
            } else if (m.token > model[c + 'Revoked']) {
              writes[c + 'Revoked'] = m.token;
            }
          } else if (m.action === 'WriteDone' || m.action === 'WriteRefused') {
            writes[c + 'Writing'] = false;
          }
        }
        for (const [k, v] of Object.entries(writes)) next[k] = v;
        unchanged(...otherKeys(Object.keys(writes)));
      },
    },
    reactors: [],
  },
});

function otherKeys(assigned) {
  return Object.keys(INITIAL_STATE).filter((k) => !assigned.includes(k));
}

const { intents } = control;

const getState = () => instance({}).getState();
const setState = (snapshot) => { instance({}).setState(snapshot); };
const init = () => { setState(INITIAL_STATE); };

const actions = {
  ACQUIRE: (data = {}) => intents.ACQUIRE(data),
  RELEASE: (data = {}) => intents.RELEASE(data),
  WRITE: (data = {}) => intents.WRITE(data),
  EXPIRE: (data = {}) => intents.EXPIRE(data),
  DELIVER: (data = {}) => intents.DELIVER(data),
};

module.exports = { instance, init, actions, getState, setState };

// Capture NDJSON traces from the real implementation (src/lease.ts) through its onStep seam.
// Run: node spec/capture.ts   → spec/traces/*.ndjson

import { mkdirSync, writeFileSync, rmSync } from 'node:fs';
import { LeaseSystem } from '../src/lease.ts';
import type { Message } from '../src/types.ts';

const enc = (m: Message) =>
  `${m.action}|${m.from}|${m.to}|${m.data.token === undefined ? '' : m.data.token}`;

function project(sys: LeaseSystem) {
  const out: Record<string, unknown> = {
    holder: sys.service.holder,
    token: sys.service.token,
    writes: sys.service.writes,
    grantWritten: sys.service.grantWritten,
  };
  for (const c of ['c0', 'c1'] as const) {
    const s = sys.clients[c];
    out[c + 'Status'] = s.status;
    out[c + 'Token'] = s.token;
    out[c + 'Writing'] = s.writing;
    out[c + 'Revoked'] = s.revoked;
  }
  out.net = [...sys.network.values()].map(enc).sort();
  return out;
}

function traced(): { sys: LeaseSystem; lines: string[] } {
  const sys = new LeaseSystem();
  const lines: string[] = [];
  let pre: Record<string, unknown> | null = null;
  let action = '';
  let data: Record<string, unknown> = {};
  sys.onStep((phase, ev) => {
    if (phase === 'pre') {
      pre = project(sys);
      if (ev.kind === 'deliver') {
        action = 'DELIVER';
        data = { i: (pre.net as string[]).indexOf(enc(ev.args.message as Message)) };
      } else {
        action = ev.name.toUpperCase();
        data = ev.name === 'expire' ? {} : { client: ev.args.client };
      }
    } else {
      lines.push(JSON.stringify({ pre, action, data, post: project(sys) }));
    }
  });
  return { sys, lines };
}

const deliverWhere = (sys: LeaseSystem, action: string) => {
  const m = sys.inFlight().find((x) => x.action === action);
  if (!m) throw new Error(`no ${action} in flight`);
  sys.deliver(m.id);
};

const scenarios: Record<string, (sys: LeaseSystem) => void> = {
  normal(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.write('c0'); sys.write('c0'); sys.deliverAll();
    sys.release('c0'); sys.release('c0'); sys.deliverAll();
  },
  refusals(sys) {
    sys.acquire('c2'); sys.release('c2'); sys.write('c2'); sys.expire();
    sys.release('c0'); sys.write('c1');
    sys.acquire('c1'); sys.acquire('c1'); sys.deliverAll();
  },
  denied_while_held(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.acquire('c1'); sys.deliverAll();
    sys.expire(); sys.deliverAll();
    sys.acquire('c1'); sys.deliverAll();
    sys.release('c1'); sys.deliverAll();
    sys.acquire('c0'); sys.deliverAll(); // grant cap
  },
  stale_write(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.write('c0'); sys.expire();
    deliverWhere(sys, 'Write'); deliverWhere(sys, 'WriteRefused');
    sys.acquire('c1'); sys.deliverAll();
  },
  revoked_before_granted(sys) {
    sys.acquire('c0'); deliverWhere(sys, 'Acquire');
    sys.expire(); deliverWhere(sys, 'Revoked'); deliverWhere(sys, 'Granted');
    sys.acquire('c0'); sys.deliverAll();
    sys.expire(); sys.deliverAll();
  },
  write_cap(sys) {
    sys.acquire('c1'); sys.deliverAll();
    for (let i = 0; i < 3; i++) { sys.write('c1'); sys.deliverAll(); }
    sys.release('c1'); sys.deliverAll();
    sys.acquire('c0'); sys.deliverAll();
    for (let i = 0; i < 2; i++) { sys.write('c0'); sys.deliverAll(); }
  },
  releasing_ignores_revoked(sys) {
    sys.acquire('c1'); sys.deliverAll();
    sys.release('c1'); sys.acquire('c1'); sys.write('c1'); sys.release('c1');
    sys.expire();
    deliverWhere(sys, 'Revoked');
    deliverWhere(sys, 'Release');
    sys.acquire('c1');
    deliverWhere(sys, 'Released');
    sys.acquire('c1'); sys.deliverAll();
  },
  one_write_per_grant_after_expire(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.write('c0'); sys.deliverAll();
    sys.expire(); sys.deliverAll();
    sys.acquire('c1'); sys.deliverAll();
    sys.write('c1'); sys.write('c1'); sys.deliverAll();
    sys.write('c1'); sys.deliverAll();
  },
  release_after_expire(sys) {
    sys.acquire('c0'); sys.deliverAll();
    sys.release('c0'); sys.expire();
    deliverWhere(sys, 'Revoked'); deliverWhere(sys, 'Release');
    sys.acquire('c0'); sys.deliverAll();
  },
};

// random schedules for breadth
for (let r = 0; r < 20; r++) {
  scenarios[`random_${r}`] = (sys) => {
    let seed = 1000 + r;
    const rnd = (n: number) => ((seed = (seed * 1103515245 + 12345) % 2147483648), seed % n);
    for (let i = 0; i < 40; i++) {
      const c = ['c0', 'c1', 'c2'][rnd(3)];
      const k = rnd(6);
      if (k === 0) sys.acquire(c);
      else if (k === 1) sys.release(c);
      else if (k === 2) sys.write(c);
      else if (k === 3) sys.expire();
      else {
        const fl = sys.inFlight();
        if (fl.length) sys.deliver(fl[rnd(fl.length)].id);
      }
    }
    sys.deliverAll();
  };
}

const dir = new URL('./traces/', import.meta.url);
rmSync(dir, { recursive: true, force: true });
mkdirSync(dir, { recursive: true });
for (const [name, run] of Object.entries(scenarios)) {
  const { sys, lines } = traced();
  run(sys);
  writeFileSync(new URL(`${name}.ndjson`, dir), lines.join('\n') + '\n');
}
console.log(`wrote ${Object.keys(scenarios).length} traces`);

